a=current_frame.ascii.split('\n')
rows=[4,12,20,28,36,44,52]; cols=[6,14,22,30,38,46,54]
R,C=7,7
subs={}; exists={}
for i in range(R):
    for j in range(C):
        if i==0 and j==6: continue  # legend
        blk=''.join(a[rows[i]+x][cols[j]:cols[j]+6] for x in range(6))
        if set(blk)=={'c'}: continue
        exists[(i,j)]=True
        subs[(i,j)]=[[a[rows[i]+2*x][cols[j]+2*y] for y in range(3)] for x in range(3)]
keys=[k for k,v in subs.items() if len(set(''.join(''.join(s) for s in v)))>1]
print('cells:',len(exists),'keys:',sorted(keys))
from collections import defaultdict
cons=defaultdict(list)
for (ki,kj) in keys:
    for x in range(3):
        for y in range(3):
            ci,cj=ki+x-1,kj+y-1
            if (ci,cj) in exists:
                cons[(ci,cj)].append((subs[(ki,kj)][x][y], (ki,kj)))
multi=[(k,v) for k,v in sorted(cons.items()) if len(v)>1]
print('cells covered by >1 key:')
for k,v in multi: print('  ',k,[(c,kk) for c,kk in v])
print('single-covered:')
for k,v in sorted(cons.items()):
    if len(v)==1: print('  ',k,v[0])
print('uncovered:',sorted(set(exists)-set(cons)))

